"use client"

import * as React from "react"
import { accentChain } from "glimm"
import { GlimmScope, type GlimmScopeHandle } from "glimm/react"

const palette = accentChain(["#0088FF", "#6155F5", "#CB30E0", "#FF2D55"])

function Bar({ width, height = 9 }: { width: number | string; height?: number }) { return <span aria-hidden="true" style={{ background: "#f1f1f2", borderRadius: 6, display: "block", height, width }} /> }

function Conversation() {
  return <div style={{ display: "grid", gap: 28, margin: "0 auto", maxWidth: 600, padding: "32px 16px 200px" }}>{[[220, ["96%", "88%", "92%", "54%"]], [164, ["90%", "94%", "38%"]]].map(([asked, replies], idx) => <div key={idx} style={{ display: "grid", gap: 18 }}><div style={{ justifySelf: "end", maxWidth: "70%", width: asked as number }}><Bar height={34} width="100%" /></div><div style={{ display: "grid", gap: 12 }}>{(replies as string[]).map((w) => <Bar key={w} width={w} />)}</div></div>)}</div>
}

function ResetScene() {
  const scope = React.useRef<GlimmScopeHandle>(null)
  const dock = React.useRef<HTMLDivElement>(null)
  const [enabled, setEnabled] = React.useState(false)
  const [seconds, setSeconds] = React.useState(3)

  React.useEffect(() => {
    if (enabled) return
    setSeconds(3)
    const interval = window.setInterval(() => setSeconds((value) => value > 1 ? value - 1 : 0), 1000)
    const timeout = window.setTimeout(() => {
      const rect = dock.current?.getBoundingClientRect()
      scope.current?.play({ anticipate: true, at: rect ? [rect.left + rect.width / 2, rect.bottom - 40] : undefined, change: () => setEnabled(true) })
    }, 3000)
    return () => { window.clearInterval(interval); window.clearTimeout(timeout) }
  }, [enabled])

  return <GlimmScope ref={scope} palette={palette} direction="btt" curve={0.2} span={0.92} bandTight={16} fade={[0.28, 0.82]} sweepMs={2700} style={{ inset: 0, position: "absolute" }}>
    <main style={{ background: "#fff", color: "#242529", fontFamily: "Inter, ui-sans-serif, system-ui, sans-serif", height: "100%", minHeight: 560, overflow: "hidden", position: "relative" }}>
      <header style={{ alignItems: "center", borderBottom: "1px solid #ececee", display: "flex", height: 44, justifyContent: "space-between", padding: "0 16px" }}><div style={{ alignItems: "center", display: "flex", gap: 12 }}><Bar height={24} width={24} /><Bar width={110} /></div><Bar height={30} width={30} /></header>
      <Conversation />
      <div style={{ bottom: 24, display: "flex", insetInline: 0, justifyContent: "center", paddingInline: 12, position: "absolute" }}><div ref={dock} style={{ maxWidth: 600, width: "100%" }}>
        {!enabled && <div style={{ background: "#f5f5f5", borderRadius: "16px 16px 0 0", color: "#8b8b8f", display: "flex", fontSize: 13, height: 48, justifyContent: "space-between", marginBottom: -16, padding: "8px 16px 0" }}><span>Usage limit reached</span><span role="timer" aria-label={`Resets in 0:0${seconds}`}>Resets in 0:0{seconds}</span></div>}
        <div style={{ background: "#fff", borderRadius: 16, boxShadow: "0 12px 35px rgba(0,0,0,.10),0 0 0 1px rgba(0,0,0,.06)", padding: 12, position: "relative" }}><textarea aria-label="Message" disabled={!enabled} rows={2} style={{ background: "transparent", border: 0, display: "block", font: "inherit", outline: 0, padding: "2px 0", resize: "none", width: "100%" }} /><div style={{ display: "flex", justifyContent: "space-between", marginTop: 12 }}><button aria-label="Add" disabled={!enabled} style={{ background: "#fafafa", border: 0, borderRadius: 999, color: "#999", fontSize: 20, height: 36, width: 36 }}>+</button><button disabled={!enabled} onClick={() => setEnabled(false)} style={{ background: enabled ? "#242529" : "#aaa", border: 0, borderRadius: 999, color: "#fff", height: 36, padding: "0 17px" }}>Send</button></div></div>
      </div></div>
    </main>
  </GlimmScope>
}

export default function GlimmUsageReset() { return <ResetScene /> }
export { GlimmUsageReset }
